"""Build an offline, one-problem-at-a-time reader."""
from pathlib import Path
import html,json,re
P=Path(__file__).resolve().parent
e=html.escape
qs=[json.loads(x) for x in (P/'numeric_problems.jsonl').read_text().splitlines()]
ans=json.loads((P/'answer_key.json').read_text()); metas=json.loads((P/'researcher_metadata.json').read_text())
proof=(P/'proof_problem.md').read_text().split('\n\n',1)[1].strip()
def paragraphs(s):
    return ''.join('<p>'+e(x+'。')+'</p>' for x in s.split('。') if x.strip())
def answer(s):
    if '/' in s:
        a,b=s.split('/'); return f'<math><mfrac><mn>{e(a)}</mn><mn>{e(b)}</mn></mfrac></math>'
    if s=='2*sqrt(15)': return '<math><mn>2</mn><msqrt><mn>15</mn></msqrt></math>'
    return e(s)
nav='<button data-page="proof"><span>中心の証明</span><strong>4点の共円を示す</strong></button>'
cards=f'<section id="proof" class="page"><div class="eyebrow">中心の証明問題 · AP01</div><h1>4点が同じ円の上にあることを示す</h1><div class="paper"><h2>問題</h2><div class="statement">{paragraphs(proof)}</div></div><div class="note">左の一覧から、関連する求値問題を選べます。各問の右側に数値解と解説を掲載しています。</div></section>'
for i,(q,a,m) in enumerate(zip(qs,ans,metas),1):
    title=e(m['title_ja']);id=q['id']
    nav+=f'<button data-page="{id}"><span>問題 {i:02}</span><strong>{title}</strong></button>'
    body=q['problem_ja'].split('\n\n')[0]
    steps=''.join(f'<li><span class="step">{j}</span><div>{e(s)}</div></li>' for j,s in enumerate(m['source_derivation_ja'],1))
    cards+=f'''<section id="{id}" class="page"><div class="eyebrow">求値問題 {i:02} / 10</div><h1>{title}</h1><div class="columns"><div class="paper question"><h2>問題</h2><div class="statement">{paragraphs(body)}</div><details class="assumption"><summary>共通の前提</summary>記載した円は非退化で、指定した交点は相異なり有限に存在するものとします。</details></div><div class="paper solution"><div class="solution-head"><h2>解答・解説</h2><button class="toggle">解答を隠す</button></div><div class="answer-body"><div class="answer"><span>答え</span><b>{answer(a['answer_exact'])}</b></div><ol>{steps}</ol></div></div></div><details class="connection"><summary>この問題と、元の証明はどうつながる？</summary><p>{e(m['connection_to_AP01_ja'])}</p><p class="muted">出典ID：{a['source_id']} · この説明は研究者用で、数値SFTの教師には含めません。</p></details></section>'''
style='''
:root{--ink:#172633;--muted:#5b6873;--line:#dde3e8;--blue:#195da6;--size:21px}*{box-sizing:border-box}body{margin:0;background:#f3f5f7;color:var(--ink);font-family:"Noto Sans CJK JP","Yu Gothic",sans-serif}button{font:inherit;cursor:pointer}aside{position:fixed;inset:0 auto 0 0;width:252px;background:#fff;border-right:1px solid var(--line);overflow:auto;padding:25px 14px}.brand{font-size:21px;font-weight:800;padding:0 12px 20px}.brand small{display:block;font-size:12px;color:var(--muted);font-weight:400;margin-top:8px}nav{display:grid;gap:5px}nav button{border:0;border-radius:8px;text-align:left;padding:10px 12px;background:none;color:var(--ink)}nav button span{display:block;color:var(--muted);font-size:12px;margin-bottom:3px}nav button strong{font-size:14px;line-height:1.6;font-weight:600}nav button:hover{background:#f0f4f9}nav button.active{background:#e9f1fc;box-shadow:inset 3px 0 var(--blue)}nav button.active strong,nav button.active span{color:var(--blue)}main{margin-left:252px;padding:0 40px 48px;max-width:1700px}.toolbar{display:flex;justify-content:space-between;align-items:center;padding:18px 0;border-bottom:1px solid var(--line);gap:14px;color:var(--muted);font-size:14px}.toolbar button,.toggle,.pager button{border:1px solid #cbd4dd;background:white;border-radius:7px;padding:8px 14px;color:var(--ink)}.toolbar button{margin-left:5px}.page{display:none;padding-top:32px}.page.active{display:block}.eyebrow{color:var(--blue);font-size:14px;font-weight:700;letter-spacing:.1em}h1{font-size:30px;line-height:1.5;margin:10px 0 28px;letter-spacing:.02em}.columns{display:grid;grid-template-columns:1fr 1fr;gap:24px;align-items:start}.paper{background:white;border:1px solid var(--line);border-radius:12px;padding:28px 30px}.paper h2{font-size:16px;color:var(--muted);margin:0 0 20px}.statement{font-size:var(--size);line-height:2;font-weight:450;line-break:strict;overflow-wrap:anywhere}.statement p{margin:0 0 22px}.statement p:last-child{margin-bottom:0;font-weight:700;color:#164d82}.assumption{margin-top:28px;color:var(--muted);font-size:13px;line-height:1.8}summary{cursor:pointer}.solution-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.solution-head h2{margin:0}.toggle{font-size:13px}.answer{display:flex;align-items:center;gap:24px;background:#eef5ff;border-radius:9px;padding:18px 22px;margin-bottom:24px}.answer span{color:var(--blue);font-size:14px}.answer b{font-family:Georgia,serif;font-size:38px;font-weight:500;color:#123b69}ol{list-style:none;padding:0;margin:0;display:grid;gap:22px}li{display:flex;gap:13px;font-size:calc(var(--size) - 3px);line-height:1.9;overflow-wrap:anywhere}.step{flex:0 0 25px;height:25px;background:#e9eef3;border-radius:50%;text-align:center;font-size:13px;line-height:25px;margin-top:6px}.connection,.note{margin-top:24px;border:1px solid var(--line);border-radius:9px;padding:18px 24px;font-size:16px;line-height:1.9;background:#fff}.connection summary{font-weight:600}.muted{color:var(--muted);font-size:13px}.pager{display:flex;justify-content:space-between;margin-top:28px}.pager button:disabled{opacity:.35;cursor:default}#proof .paper{max-width:860px}.hidden{display:none}@media(min-width:1550px){main{padding:0 60px 48px}.paper{padding:34px 38px}}@media(max-width:1150px){.columns{grid-template-columns:1fr}main{padding:0 28px 40px}.paper{max-width:850px}}@media(max-width:680px){aside{position:relative;width:100%;max-height:210px;border-bottom:1px solid var(--line);padding:12px}.brand{font-size:18px;padding-bottom:8px}.brand small{display:none}nav{display:flex;overflow:auto}nav button{min-width:150px}main{margin:0;padding:0 16px 30px}.toolbar>span{display:none}h1{font-size:25px}.paper{padding:22px}.statement{font-size:20px}}@media print{aside,.toolbar,.pager,.toggle{display:none}main{margin:0;padding:0}.page{display:block;break-before:page}.columns{display:block}.paper{border:0}.answer-body.hidden{display:block}body{background:white}}
'''
script='''
const pages=[...document.querySelectorAll('.page')];let index=0;let size=21;
function show(id){index=Math.max(0,pages.findIndex(p=>p.id===id));pages.forEach((p,i)=>p.classList.toggle('active',i===index));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===pages[index].id));document.getElementById('prev').disabled=index===0;document.getElementById('next').disabled=index===pages.length-1;document.getElementById('position').textContent=index===0?'中心の証明問題':`問題 ${index} / 10`;window.scrollTo(0,0)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.page});window.onhashchange=()=>show(location.hash.slice(1));document.getElementById('prev').onclick=()=>location.hash=pages[Math.max(0,index-1)].id;document.getElementById('next').onclick=()=>location.hash=pages[Math.min(pages.length-1,index+1)].id;
document.querySelectorAll('.toggle').forEach(b=>b.onclick=()=>{let content=b.closest('.solution').querySelector('.answer-body');content.classList.toggle('hidden');b.textContent=content.classList.contains('hidden')?'解答を表示':'解答を隠す'});
document.getElementById('larger').onclick=()=>{size=Math.min(29,size+2);document.documentElement.style.setProperty('--size',size+'px')};document.getElementById('smaller').onclick=()=>{size=Math.max(17,size-2);document.documentElement.style.setProperty('--size',size+'px')};show(location.hash.slice(1)||'PN01');
'''
page=f'''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>幾何問題集 — 問題と解答</title><style>{style}</style><aside><div class="brand">幾何問題集<small>証明1題と関連する求値10問</small></div><nav>{nav}</nav></aside><main><header class="toolbar"><span id="position"></span><div>文字サイズ <button id="smaller" aria-label="文字を小さく">A−</button><button id="larger" aria-label="文字を大きく">A＋</button></div></header>{cards}<div class="pager"><button id="prev">← 前の問題</button><button id="next">次の問題 →</button></div></main><script>{script}</script></html>'''
(P/'review.html').write_text(page)
print(P/'review.html')
